import { createRouter, createWebHistory } from 'vue-router'
import store from '../store'
import { socket } from '@/socket'

// Composants
import Login from '../views/Login.vue'
import Register from '../views/Register.vue'
import VerifyEmail from '../views/VerifyEmail.vue'
import Dashboard from '../views/Dashboard.vue'
import CryptoDetail from '../views/CryptoDetail.vue'

const routes = [
  {
    path: '/',
    redirect: '/dashboard'
  },
  {
    path: '/login',
    name: 'Login',
    component: Login,
    meta: { requiresGuest: true }
  },
  {
    path: '/register',
    name: 'Register',
    component: Register,
    meta: { requiresGuest: true }
  },
  {
    path: '/verify-email',
    name: 'verify-email',
    component: VerifyEmail,
    meta: { requiresGuest: true }
  },
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: Dashboard,
    meta: { requiresAuth: true }
  },
  {
    path: '/wallet',
    name: 'Wallet',
    component: () => import('../views/Wallet.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/trade/:symbol',
    name: 'Trade',
    component: () => import('../views/Trade.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/crypto/:symbol',
    name: 'CryptoDetail',
    component: CryptoDetail,
    meta: { requiresAuth: true }
  },
  {
    path: '/transactions',
    name: 'TransactionsList',
    component: () => import('../views/TransactionsList.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/analysis',
    name: 'Analysis',
    component: () => import('../views/Analysis.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/commission-settings',
    name: 'CommissionSettings',
    component: () => import('../views/CommissionSettings.vue'),
    meta: { requiresAdmin: true }
  },
  {
    path: '/commission-analysis',
    name: 'CommissionAnalysis',
    component: () => import('../views/CommissionAnalysis.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/admin/login',
    name: 'AdminLogin',
    component: () => import('../views/AdminLogin.vue'),
    meta: { requiresGuest: true }
  },
  {
    path: '/admin/dashboard',
    name: 'AdminDashboard',
    component: () => import('../views/AdminDashboard.vue'),
    meta: { requiresAdmin: true }
  },
  {
    path: '/transactions-summary',
    name: 'UserTransactionsSummary',
    component: () => import('../views/UserTransactionsSummary.vue'),
    meta: { requiresAdmin: true }
  },
  {
    path: '/account',
    name: 'Account',
    component: () => import('../views/Account.vue'),
    meta: { requiresAuth: true }
  }
]

const router = createRouter({
  history: createWebHistory(),
  routes
})

// Middleware de navigation global
router.beforeEach(async (to, from, next) => {
  // Routes publiques qui ne nécessitent pas d'authentification
  const publicRoutes = ['/login', '/register', '/admin/login']

  try {
    // Si on n'est pas sur une route publique et qu'on n'est pas authentifié
    if (!publicRoutes.includes(to.path)) {
      // Récupérer le token
      const token = localStorage.getItem('token')

      if (!token) {
        // Rediriger vers la page de connexion si pas de token
        return next('/login')
      }

      // Si l'utilisateur n'est pas encore initialisé dans le store
      if (!store.getters['auth/isAuthenticated']) {
        // Initialiser l'authentification
        await store.dispatch('auth/init')

        // Initialiser la connexion socket
        if (!socket.connected) {
          socket.connect()
          socket.emit('authenticate', token)
        }
      }
    }

    // Continuer la navigation
    next()
  } catch (error) {
    console.error('Erreur d\'authentification:', error)
    // En cas d'erreur, rediriger vers la page de connexion
    localStorage.removeItem('token')
    localStorage.removeItem('user')
    next('/login')
  }
})

export default router
